import React, { useEffect, useState } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';

function App() {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Check if the user is authenticated
    fetch('/api/auth/user/')
      .then(res => res.json())
      .then(data => {
        if (data.authenticated) {
          setUser(data);
        }
        setLoading(false);
      })
      .catch(err => {
        console.error("Error fetching user", err);
        setLoading(false);
      });
  }, []);

  const handleLogin = () => {
    // Redirect to Django MSAL login endpoint
    window.location.href = '/api/auth/login/';
  };

  const handleLogout = () => {
    fetch('/api/auth/logout/', { method: 'POST' })
      .then(() => {
        setUser(null);
        window.location.href = '/';
      });
  };

  if (loading) {
    return <div style={{ padding: '2rem', textAlign: 'center' }}>Loading App...</div>;
  }

  return (
    <Router>
      <div className="App">
        <nav style={{ padding: '1rem 2rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h2 style={{ margin: 0, color: '#0078D4' }}>AP Automation Portal</h2>
          {user ? (
            <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
              <span style={{ fontSize: '14px', color: '#555' }}>
                Welcome, <strong>{user.username}</strong> ({user.role})
              </span>
              <button onClick={handleLogout} style={{ backgroundColor: '#d13438' }}>Logout</button>
            </div>
          ) : (
            <button onClick={handleLogin}>Login with Microsoft</button>
          )}
        </nav>

        <main style={{ padding: '2rem', maxWidth: '1200px', margin: '0 auto' }}>
          <Routes>
            <Route path="/" element={
              user ? (
                <div style={{ backgroundColor: '#f9f9f9', padding: '2rem', borderRadius: '8px', border: '1px solid #eaeaea' }}>
                  <h3>Dashboard</h3>
                  <p style={{ fontSize: '16px' }}>You are logged in as a <strong>{user.role}</strong>.</p>

                  {/* Role based rendering */}
                  <div style={{ marginTop: '1.5rem', padding: '1.5rem', backgroundColor: 'white', borderRadius: '6px', borderLeft: '4px solid #0078D4' }}>
                    {user.role === 'STORE_ACCOUNTANT' && (
                      <>
                        <h4 style={{ marginTop: 0 }}>Accountant Tasks</h4>
                        <p>• Upload scanned invoice copies.</p>
                        <p>• Perform manual corrections on extracted data tables.</p>
                        <p>• Mark line items for payment based on fund availability.</p>
                      </>
                    )}
                    {user.role === 'STORE_MANAGER' && (
                      <>
                        <h4 style={{ marginTop: 0 }}>Manager Tasks</h4>
                        <p>• Handle one-time activities (KYC, Vendor details).</p>
                        <p>• Provide final approval or rejection of payment line items.</p>
                      </>
                    )}
                    {user.role === 'AP_TEAM' && (
                      <>
                        <h4 style={{ marginTop: 0 }}>AP Team Tasks</h4>
                        <p>• Oversee end-to-end reconciliation.</p>
                        <p>• Download/Upload payment files for ICICI/SBI.</p>
                        <p>• Handle bank portal rejections.</p>
                      </>
                    )}
                  </div>
                </div>
              ) : (
                <div style={{ textAlign: 'center', padding: '4rem 2rem', backgroundColor: '#f9f9f9', borderRadius: '8px', border: '1px solid #eaeaea' }}>
                  <h3 style={{ marginBottom: '1.5rem' }}>Welcome to AP Automation Portal</h3>
                  <p style={{ marginBottom: '2rem', color: '#666' }}>Please authenticate using your Microsoft organizational account to access the system.</p>
                  <button onClick={handleLogin} style={{ padding: '12px 24px', fontSize: '16px' }}>
                    Login with Microsoft
                  </button>
                </div>
              )
            } />
          </Routes>
        </main>
      </div>
    </Router>
  );
}

export default App;
